from pathlib import Path
import hashlib,json,math,os,plistlib,re,statistics,subprocess,tempfile
root=Path('/private/tmp/logex-audit-130-02gwayfm');image=root/'exfat-raw.dmg';mount=root/'exfat'
os.chdir(root/'current-6ce06c13');os.environ['PATH']=str(Path.home()/'.cargo/bin')+os.pathsep+os.environ.get('PATH','')
binaries={'original':root/'baseline-v3-09a63f55-publication-tests','candidate':root/'bundled-6ce06c13-publication-tests'}
result_path=root/'bundled-6ce06c13-performance.jsonl'
def attached():
 records=plistlib.loads(subprocess.check_output(['hdiutil','info','-plist']));matches=[x for x in records.get('images',[])if Path(x['image-path']).resolve()==image.resolve()];assert len(matches)<=1
 return matches[0] if matches else None
assert image.is_file() and not image.is_symlink() and all(p.is_file()for p in binaries.values()) and attached() is None
assert mount.is_dir() and not mount.is_symlink() and os.stat(mount).st_dev==os.stat(image.parent).st_dev
subprocess.check_call(['hdiutil','attach',str(image),'-mountpoint',str(mount),'-nobrowse'])
try:
 selected=attached();assert selected is not None and any(x.get('mount-point')==str(mount)for x in selected['system-entities'])
 volume=plistlib.loads(subprocess.check_output(['diskutil','info','-plist',str(mount)]));assert volume['FilesystemType']=='exfat'
 with tempfile.TemporaryDirectory(prefix='logex-live-bundle-diag-',dir=mount) as temp, result_path.open('w') as output:
  metadata={'kind':'environment','original':'09a63f555db19a03850ce5eba6f149957febaf3b','candidate':'6ce06c13628dd05e3403e5c7e1a5e4f1c25147fb','candidate_source_archive_sha256':'151a72f28c63b886c2a48cebbabd512697a8991e72442ee0e7946fdf0e8631db','runner_source':Path(__file__).read_text(),'binary_sha256':{k:hashlib.sha256(p.read_bytes()).hexdigest()for k,p in binaries.items()},'rustc':subprocess.check_output(['rustc','-Vv'],text=True),'os':subprocess.check_output(['sw_vers'],text=True),'hardware':subprocess.check_output(['sysctl','-n','hw.model','hw.memsize','hw.ncpu'],text=True),'filesystem':'disposable ExFAT image on internal APFS','device':os.stat(temp).st_dev,'conditions':'Five alternating process pairs x three fresh datasets per profile. Same fixture v3 digests, tip hashes and exact row/progress/reopen oracles. Original uses separate row/progress APIs; candidate uses combined ingestion with bounded ordered 32 MiB/64-call/five-second recovery and final checkpoint included, no explicit strong checkpoint request. Current live bundles and index-checkpoint implementation, not prototype. No concurrent remote builds/tests; fresh directories, OS caches not evicted. No production volume contents accessed. Storage-call timings, not network throughput.'}
  assert metadata['binary_sha256']['original']=='f976f37e6c75fa870e0178656641d321ba35380b345eeefaaaa2013053f2f7c7'
  assert metadata['binary_sha256']['candidate']=='34218a1831f39c904dfc6a53e4b39b48e1eb2fb5b046aafc52655803f7026703'
  output.write(json.dumps(metadata)+'\n');output.flush()
  profiles=[('tiny-history',2048,1,'historical',False,128),('short-history',128,128,'historical',False,2048),('per-block-live',128,128,'live',True,2048),('one-row-live',128,1,'live',True,2048)]
  labels=list(binaries)
  for profile,blocks,rows,route,each,batch in profiles:
   for pair in range(5):
    for label in (labels if pair%2==0 else labels[::-1]):
     env={**os.environ,'TMPDIR':temp,'LOGEX_PUBLICATION_HEADER_FIELDS':'minimal','LOGEX_PUBLICATION_BLOCKS':str(blocks),'LOGEX_PUBLICATION_ROWS_PER_BLOCK':str(rows),'LOGEX_PUBLICATION_HISTORY_BLOCKS':str(batch),'LOGEX_PUBLICATION_SEGMENT_ROWS':'1000000','LOGEX_PUBLICATION_WARM_HEADERS':'8192','LOGEX_PUBLICATION_REPEATS':'3','LOGEX_PUBLICATION_ROUTE':route,'LOGEX_PUBLICATION_CHECKPOINT_EACH_BLOCK':str(int(each)),'LOGEX_PUBLICATION_DURABLE_CHECKPOINT':'0'}
     logpath=root/f'bundled-6ce06c13-{profile}-{pair}-{label}.log'
     with logpath.open('w') as log:r=subprocess.run(['/usr/bin/time','-l',str(binaries[label]),'benchmark_sync_storage_publication','--ignored','--nocapture','--test-threads=1'],env=env,stdout=log,stderr=subprocess.STDOUT)
     if r.returncode:raise RuntimeError(str(logpath))
     for line in logpath.read_text().splitlines():
      if '{' in line:
       try:record=json.loads(line[line.index('{'):])
       except json.JSONDecodeError:continue
       output.write(json.dumps({**record,'profile':profile,'pair':pair,'revision':label})+'\n')
      elif 'maximum resident set size' in line:output.write(json.dumps({'kind':'rss','profile':profile,'pair':pair,'revision':label,'bytes':int(line.split()[0])})+'\n')
     output.flush();print(profile,pair,label,'passed',flush=True)
  records=[json.loads(x)for x in result_path.read_text().splitlines()]
  for profile,*_ in profiles:
   configs=[r for r in records if r.get('kind')=='config'and r['profile']==profile]
   assert len(configs)==10 and len({r['fixture_digest']for r in configs})==1 and len({r['tip_hash']for r in configs})==1
   vals={k:[r['elapsed_ms']for r in records if r.get('kind')=='sample'and r['revision']==k and r['profile']==profile]for k in labels};assert all(len(v)==15 for v in vals.values())
   med={k:statistics.median(v)for k,v in vals.items()};summary={'kind':'summary','profile':profile,'median_ms':med,'p95_ms':{k:sorted(v)[math.ceil(.95*len(v))-1]for k,v in vals.items()},'change_percent':100*(med['candidate']/med['original']-1),'samples':{k:len(v)for k,v in vals.items()}}
   output.write(json.dumps(summary)+'\n');print(summary,flush=True)

finally:
 selected=attached()
 if selected is not None:
  assert any(x.get('mount-point')==str(mount)for x in selected['system-entities'])
  devices=[x['dev-entry']for x in selected['system-entities']if re.fullmatch(r'/dev/disk[0-9]+',x.get('dev-entry',''))];assert len(devices)==1
  subprocess.check_call(['hdiutil','detach',devices[0]])
 assert attached() is None
 print('Disposable image detached',flush=True)
